package edu.swiftattend;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;

@RestController @RequestMapping("/api/timetable")
public class TimetableController {
    private final JdbcTemplate db;TimetableController(JdbcTemplate d){db=d;}
    record Entry(@NotBlank String subjectId,@Min(0) @Max(6) int dayOfWeek,@NotBlank String startTime,@NotBlank String endTime,@NotBlank @Size(max=50) String roomNumber,@NotBlank @Size(max=60) String batch,@Pattern(regexp="Lecture|Lab Session|Tutorial|Seminar|Evaluation") String classType){}
    @GetMapping List<Map<String,Object>> list(@org.springframework.security.core.annotation.AuthenticationPrincipal String who,org.springframework.security.core.Authentication auth){String sql="SELECT c.id,c.subject_id AS \"subjectId\",s.code AS \"subjectCode\",s.name AS \"subjectName\",c.day_of_week AS \"dayOfWeek\",to_char(c.start_time,'HH24:MI') AS \"startTime\",to_char(c.end_time,'HH24:MI') AS \"endTime\",c.room_number AS \"roomNumber\",c.batch,c.class_type AS \"classType\" FROM class_schedule c JOIN subject s ON s.id=c.subject_id WHERE ";if(auth.getAuthorities().iterator().next().getAuthority().equals("ROLE_TEACHER"))return db.queryForList(sql+"c.teacher_id=? ORDER BY c.day_of_week,c.start_time",UUID.fromString(who));return db.queryForList(sql+"s.department=(SELECT department FROM app_user WHERE id=?) ORDER BY c.day_of_week,c.start_time",UUID.fromString(who));}
    @GetMapping("/active") Map<String,Object> active(@org.springframework.security.core.annotation.AuthenticationPrincipal String who,org.springframework.security.core.Authentication auth){int dow=LocalDate.now().getDayOfWeek().getValue()%7;LocalTime now=LocalTime.now();String role=auth.getAuthorities().iterator().next().getAuthority();String filter=role.equals("ROLE_TEACHER")?"c.teacher_id=CAST(? AS UUID)":"s.department=(SELECT department FROM app_user WHERE id=CAST(? AS UUID))";return db.query("SELECT c.id,c.subject_id,s.code,s.name,c.room_number,c.batch,c.start_time,c.end_time FROM class_schedule c JOIN subject s ON s.id=c.subject_id WHERE c.day_of_week=? AND c.start_time<=? AND c.end_time>? AND "+filter+" ORDER BY c.start_time LIMIT 1",rs->rs.next()?Map.of("active",true,"scheduleId",rs.getObject(1),"subjectId",rs.getObject(2),"subjectCode",rs.getString(3),"subjectName",rs.getString(4),"roomNumber",rs.getString(5),"batch",rs.getString(6),"startTime",rs.getString(7),"endTime",rs.getString(8)):Map.of("active",false),dow,now,now,who);}
    @PostMapping @PreAuthorize("hasRole('TEACHER')") @ResponseStatus(HttpStatus.CREATED)
    Map<String,Object> create(@org.springframework.security.core.annotation.AuthenticationPrincipal String who,@Valid @RequestBody Entry e){UUID teacher=UUID.fromString(who),subject=AttendanceController.uuid(e.subjectId());LocalTime start,end;try{start=LocalTime.parse(e.startTime());end=LocalTime.parse(e.endTime());}catch(Exception ex){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Schedule times must use HH:MM format.");}if(!start.isBefore(end))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Start time must be before end time.");if(db.queryForObject("SELECT count(*) FROM subject WHERE id=? AND teacher_id=?",Integer.class,subject,teacher)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Subject not found.");Integer conflicts=db.queryForObject("SELECT count(*) FROM class_schedule c WHERE c.day_of_week=? AND c.start_time<? AND c.end_time>? AND (c.teacher_id=? OR c.room_number=? OR c.batch=?)",Integer.class,e.dayOfWeek(),end,start,teacher,e.roomNumber(),e.batch());if(conflicts>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"This time conflicts with a teacher, room, or batch schedule.");UUID id=UUID.randomUUID();db.update("INSERT INTO class_schedule(id,subject_id,teacher_id,day_of_week,start_time,end_time,room_number,batch,class_type) VALUES(?,?,?,?,?,?,?,?,?)",id,subject,teacher,e.dayOfWeek(),start,end,e.roomNumber(),e.batch(),e.classType()==null?"Lecture":e.classType());return Map.of("id",id,"message","Class added to the timetable.");}
}
